import { validateNodes } from './validate-nodes.mjs';

export function planBuild(nodes) {
  validateNodes(nodes);
  if (nodes.length === 0) return [];

  const inputIndex = new Map(nodes.map((node, index) => [node.id, index]));
  const inDegree = new Map();
  const dependents = new Map();

  for (const node of nodes) {
    inDegree.set(node.id, 0);
    dependents.set(node.id, []);
  }

  for (const node of nodes) {
    const seen = new Set();
    for (const dep of node.dependsOn || []) {
      if (seen.has(dep)) continue;
      seen.add(dep);
      inDegree.set(node.id, inDegree.get(node.id) + 1);
      dependents.get(dep).push(node.id);
    }
  }

  const scheduled = new Set();
  const result = [];

  while (result.length < nodes.length) {
    let pick = null;
    let pickIndex = Infinity;

    for (const node of nodes) {
      const id = node.id;
      if (scheduled.has(id)) continue;
      if (inDegree.get(id) !== 0) continue;
      const index = inputIndex.get(id);
      if (index < pickIndex) {
        pickIndex = index;
        pick = id;
      }
    }

    if (pick === null) {
      throw new Error('cycle');
    }

    scheduled.add(pick);
    result.push(pick);
    for (const dependentId of dependents.get(pick)) {
      inDegree.set(dependentId, inDegree.get(dependentId) - 1);
    }
  }

  return result;
}

