export function validateNodes(nodes) {
  if (!Array.isArray(nodes)) {
    throw new TypeError('nodes must be an array');
  }

  const nodeIds = new Set();
  const entries = [];

  for (const node of nodes) {
    if (node === null || typeof node !== 'object' || Array.isArray(node)) {
      throw new TypeError('node must be an object');
    }

    const { id, dependsOn } = node;
    if (typeof id !== 'string' || id.length === 0) {
      throw new TypeError('node id must be a nonempty string');
    }
    if (nodeIds.has(id)) {
      throw new Error('duplicate node id');
    }
    nodeIds.add(id);

    let deps = [];
    if (dependsOn !== undefined) {
      if (!Array.isArray(dependsOn)) {
        throw new TypeError('dependsOn must be an array');
      }
      const seenDep = new Set();
      for (const dep of dependsOn) {
        if (typeof dep !== 'string' || dep.length === 0) {
          throw new TypeError('dependency id must be a nonempty string');
        }
        if (!seenDep.has(dep)) {
          seenDep.add(dep);
          deps.push(dep);
        }
      }
    }

    entries.push({ id, deps });
  }

  for (const { id, deps } of entries) {
    for (const dep of deps) {
      if (!nodeIds.has(dep)) {
        throw new Error('missing dependency');
      }
      if (dep === id) {
        throw new Error('cycle');
      }
    }
  }

  const inDegree = new Map();
  const outgoing = new Map();
  for (const { id } of entries) {
    inDegree.set(id, 0);
    outgoing.set(id, []);
  }
  for (const { id, deps } of entries) {
    inDegree.set(id, deps.length);
    for (const dep of deps) {
      outgoing.get(dep).push(id);
    }
  }

  const queue = [];
  for (const [id, degree] of inDegree) {
    if (degree === 0) queue.push(id);
  }

  let processed = 0;
  while (queue.length > 0) {
    const current = queue.shift();
    processed += 1;
    for (const next of outgoing.get(current)) {
      const nextDegree = inDegree.get(next) - 1;
      inDegree.set(next, nextDegree);
      if (nextDegree === 0) queue.push(next);
    }
  }

  if (processed !== entries.length) {
    throw new Error('cycle');
  }
}

